\section{Local Function Declarations}
\seclabel{local-fn-decls}
\begin{Grammar}
\emph{LocalFnDecl} &::=&
\option{\emph{LocalFnMods}}
\emph{NamedFnHeaderFront} \emph{FnHeaderClause} \EXP{=}
\emph{Expr} \\

\emph{LocalFnMods} &::=& \emph{LocalFnMod}$^+$\\

\emph{LocalFnMod} &::=& \KWD{atomic} $|$ \KWD{io}\\
\end{Grammar}


Functions can be declared within expression blocks (described in
\secref{block-expr}) via the same syntax as is used for top-level
function declarations (described in \chapref{functions})
except that locally declared functions must not be operators
and must not include the modifiers \KWD{private} and \KWD{test}.
As with top-level function declarations, locally declared functions in a
single scope are allowed to be overloaded and mutually recursive.

// Probe driver: run the BYTECODE-COMPILER phase order (disambiguate, typecheck,
// desugar, overload-rewrite, codegen) with the INTERPRETER's prelude in scope
// (FortressLibrary / FortressBuiltin / AnyType) instead of the compiler's
// (CompilerLibrary / CompilerBuiltin / AnyType).
//
// This is exactly Pavol's proposal -- "use FortressLibrary for the compiler as
// well" -- expressed without editing a tracked file: Shell.useInterpreterLibraries()
// and Shell.setPhaseOrder() are both public, so the same switch WellKnownNames
// flips per subcommand can be flipped here.
//
// Usage:  java -cp <fortress classpath>:. WorldFlip [-stop <phase>] <file.fss|.fsi>
//   -stop disambiguate | typecheck | desugar   selects a truncated phase order,
//   so we can see which phase each error batch comes from; default = full
//   compilerPhaseOrder (through CODEGEN).
import com.sun.fortress.Shell;
import com.sun.fortress.compiler.phases.PhaseOrder;
import edu.rice.cs.plt.tuple.Option;
import java.util.Arrays;
import java.util.ArrayList;
import java.util.List;

public class WorldFlip {
    public static void main(String[] args) throws Throwable {
        List<String> a = new ArrayList<String>(Arrays.asList(args));
        PhaseOrder[] order = PhaseOrder.compilerPhaseOrder;
        String stop = "codegen";
        if (a.size() >= 2 && a.get(0).equals("-stop")) {
            stop = a.get(1);
            a = a.subList(2, a.size());
            if (stop.equals("disambiguate"))      order = PhaseOrder.disambiguatePhaseOrder;
            else if (stop.equals("typecheck"))    order = PhaseOrder.typecheckPhaseOrder;
            else if (stop.equals("desugar"))      order = PhaseOrder.desugarPhaseOrder;
            else throw new RuntimeException("unknown -stop " + stop);
        }
        System.out.println("### world=INTERPRETER-LIBRARIES (FortressLibrary/FortressBuiltin/AnyType)"
                           + "  phases=" + stop + "  target=" + a);
        Shell.useInterpreterLibraries();
        Shell.setTypeChecking(true);
        Shell.setScala(true);
        if (stop.equals("desugar")) Shell.setObjExprDesugaring(true);
        Shell.setPhaseOrder(order);
        int rc = Shell.compilerPhases(a, Option.<String>none(), "compile");
        System.out.println("### rc=" + rc);
        System.exit(rc);
    }
}

// Probe driver: run the compile path's later phases (DESUGAR, OVERLOADREWRITE,
// CODEGEN) on the INTERPRETER's library.  Two ways past the checker's crash on
// `nat`-kinded static parameters:
//   (1) leave TYPECHECK out of the phase order  (-order nocheck-*)
//   (2) keep it in and catch its failures per declaration  (-order full, with
//       -Dprobe.tolerant=true and the shadow classes of make-shadows.sh)
//
// Built only from public Shell entry points, exactly as ../WorldFlip.java is;
// no tracked file is modified.
//
// Usage: java -cp <shadow-classes>:<fortress classpath>:. PhaseProbe [flags] <file.fss|.fsi>
//   -order <name>     the phase order, below
//   -compilerlib      the compiler's prelude instead of the interpreter's (control)
//   -interpdesugar    the interpreter's desugaring settings instead of the
//                     compile path's (default: the compile path's)
//
// Phase orders:
//   full        compilerPhaseOrder, unchanged (TYPECHECK in)   -- reference
//   nocheck-pretc   through PRETYPECHECKDESUGAR, no TYPECHECK
//   nocheck-intlit  through INTEGERLITERALFOLDING, no TYPECHECK
//   nocheck-desugar through DESUGAR,              no TYPECHECK
//   nocheck-ovld    through OVERLOADREWRITE,      no TYPECHECK
//   nocheck-codegen through CODEGEN,              no TYPECHECK
//   typecheck       the compile path's typecheckPhaseOrder, for error counts
//   check-codegen   the full compiler order (TYPECHECK in) -- same as full
import com.sun.fortress.Shell;
import com.sun.fortress.compiler.phases.PhaseOrder;
import edu.rice.cs.plt.tuple.Option;
import java.util.Arrays;
import java.util.ArrayList;
import java.util.List;

public class PhaseProbe {

    static PhaseOrder[] order(String name) {
        PhaseOrder P = PhaseOrder.PREDISAMBIGUATEDESUGAR;
        PhaseOrder D = PhaseOrder.DISAMBIGUATE;
        PhaseOrder G = PhaseOrder.GRAMMAR;
        PhaseOrder T = PhaseOrder.PRETYPECHECKDESUGAR;
        PhaseOrder I = PhaseOrder.INTEGERLITERALFOLDING;
        PhaseOrder C = PhaseOrder.TYPECHECK;
        PhaseOrder S = PhaseOrder.DESUGAR;
        PhaseOrder O = PhaseOrder.OVERLOADREWRITE;
        PhaseOrder Z = PhaseOrder.CODEGEN;
        if (name.equals("full") || name.equals("check-codegen"))
            return PhaseOrder.compilerPhaseOrder;
